/**
 * @summary Explore published books (filtered, no adult content)
 */
export const getExploreBooksUrl = (params?: ExploreBooksParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/explore?${stringifiedParams}`
    : `/api/explore`;
};

export const exploreBooks = async (
  params?: ExploreBooksParams,
  options?: RequestInit,
): Promise<ExploreFeed> => {
  return customFetch<ExploreFeed>(getExploreBooksUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getExploreBooksQueryKey = (params?: ExploreBooksParams) => {
  return [`/api/explore`, ...(params ? [params] : [])] as const;
};

export const getExploreBooksQueryOptions = <
  TData = Awaited<ReturnType<typeof exploreBooks>>,
  TError = ErrorType<unknown>,
>(
  params?: ExploreBooksParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof exploreBooks>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getExploreBooksQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof exploreBooks>>> = ({
    signal,
  }) => exploreBooks(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof exploreBooks>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ExploreBooksQueryResult = NonNullable<
  Awaited<ReturnType<typeof exploreBooks>>
>;
export type ExploreBooksQueryError = ErrorType<unknown>;

/**
 * @summary Explore published books (filtered, no adult content)
 */

export function useExploreBooks<
  TData = Awaited<ReturnType<typeof exploreBooks>>,
  TError = ErrorType<unknown>,
>(
  params?: ExploreBooksParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof exploreBooks>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getExploreBooksQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

